<script lang="ts">
	import type { DiskInfo, ManualLayout, ManualPartition, PartitionRole } from '$lib/types';
	import { ROLE_BOOT, ROLE_ROOT } from '$lib/types';
	// @ts-expect-error — generated by Wails
	import { GetManualLayout, SaveManualLayout } from '@wails/go/gui/App.js';
	import { installState, computeFreeMB, setPartitionRole } from '$lib/store.svelte';
	import { t } from '$lib/i18n';
	import './ManualPartitionPage.css';

	let { disk }: { disk: DiskInfo | null } = $props();

	// Typed role option lists so each-block bindings stay PartitionRole.
	const ROLE_OPTIONS: PartitionRole[] = [ROLE_BOOT, ROLE_ROOT];
	const ADD_ROLE_OPTIONS: PartitionRole[] = [ROLE_BOOT, ROLE_ROOT];

	let layout: ManualLayout | null = $state(null);
	let loading = $state(false);
	let error = $state<string | null>(null);
	let saving = $state(false);

	// Delete confirmation target (partition index), or null when closed.
	let deleteTargetIndex = $state<number | null>(null);

	// "Add new partition" controls.
	let addSizeMB = $state<number>(0);
	let addUseRemaining = $state(false);
	let addRole = $state<PartitionRole>(ROLE_ROOT);

	// Derived free / allocated space (MB).
	const freeMB = $derived.by(() => (layout ? computeFreeMB(layout) : 0));
	const allocatedMB = $derived.by(() =>
		layout ? layout.partitions.reduce((sum, p) => sum + Math.max(p.sizeMB, 0), 0) : 0,
	);
	const diskSizeMB = $derived.by(() => (layout ? layout.diskSizeMB : 0));
	const usedPct = $derived.by(() =>
		diskSizeMB > 0 ? Math.min(100, Math.round((allocatedMB / diskSizeMB) * 100)) : 0,
	);

	async function loadLayout(): Promise<void> {
		if (!disk) return;
		loading = true;
		error = null;
		try {
			const fetched = await GetManualLayout(disk.path);
			layout = fetched;
			installState.manualLayout = fetched;
		} catch (err) {
			error = `Failed to load partition layout: ${err instanceof Error ? err.message : String(err)}`;
		} finally {
			loading = false;
		}
	}

	// Persist the current layout to the backend app state.
	async function persist(): Promise<void> {
		if (!layout) return;
		saving = true;
		try {
			await SaveManualLayout(layout);
		} catch (err) {
			error = `Failed to save layout: ${err instanceof Error ? err.message : String(err)}`;
		} finally {
			saving = false;
		}
	}

	// Keep the shared store in sync with local mutations so validation and the
	// commit step see the latest layout.
	function touch(): void {
		installState.manualLayout = layout;
	}

	function roleLabel(role: PartitionRole): string {
		return t('manual.role.' + role);
	}

	// Filesystem locked to a role: Boot → vfat (ESP), Root → selected mode fs.
	function fsForRole(role: PartitionRole): string {
		if (role === ROLE_BOOT) return 'vfat';
		return installState.fileSystem || 'ext4';
	}

	function setRole(part: ManualPartition, role: PartitionRole): void {
		if (!layout) return;
		setPartitionRole(layout.partitions, part.index, role);
		touch();
		void persist();
	}

	function nextIndex(): number {
		if (!layout || layout.partitions.length === 0) return 0;
		return layout.partitions.reduce((max, p) => Math.max(max, p.index), -1) + 1;
	}

	function canDelete(part: ManualPartition): boolean {
		// Designated Boot/Root partitions must never be deleted.
		return part.role !== ROLE_BOOT && part.role !== ROLE_ROOT;
	}

	function addPartition(): void {
		if (!layout || !disk) return;
		const sizeMB = addUseRemaining ? freeMB : addSizeMB;
		if (sizeMB <= 0) {
			error = t('manual.addTooSmall');
			return;
		}
		const newPart: ManualPartition = {
			index: nextIndex(),
			path: '',
			sizeMB,
			role: addRole,
			existingFstype: '',
		};
		layout.partitions.push(newPart);
		touch();
		void persist();
		// Reset add controls.
		addSizeMB = 0;
		addUseRemaining = false;
		error = null;
	}

	function requestDelete(index: number): void {
		deleteTargetIndex = index;
	}

	function confirmDelete(): void {
		if (layout === null || deleteTargetIndex === null) return;
		const before = layout.partitions.length;
		layout.partitions = layout.partitions.filter((p) => p.index !== deleteTargetIndex);
		if (layout.partitions.length !== before) {
			touch();
			void persist();
		}
		deleteTargetIndex = null;
	}

	// Reload whenever the selected disk changes.
	$effect(() => {
		void loadLayout();
	});
</script>

<div class="manual">
	{#if error}
		<div class="state-message error">
			<p>{error}</p>
		</div>
	{/if}

	{#if loading}
		<div class="state-message">
			<div class="spinner"></div>
			<p>{t('page.diskSelection.scanPartitions')}</p>
		</div>
	{:else if !layout}
		<div class="state-message">
			<p>{t('manual.noPartitions')}</p>
		</div>
	{:else}
		<!-- Free-space track -->
		<div class="free-track">
			<div class="free-label">
				<span>{t('manual.allocated')} {allocatedMB} {t('unit.mb')}</span>
				<span class="free-of">{t('manual.of')} {diskSizeMB} {t('unit.mb')}</span>
				<span class="free-free">{t('manual.free')} {freeMB} {t('unit.mb')}</span>
			</div>
			<div class="free-bar" role="progressbar" aria-valuenow={usedPct} aria-valuemin={0} aria-valuemax={100}>
				<div class="free-used" style="--pct: {usedPct}%"></div>
			</div>
		</div>

		<!-- Partition table -->
		<div class="partition-editor">
			<table class="editor-table">
				<thead>
					<tr>
						<th>{t('disk.name')}</th>
						<th>{t('disk.size')}</th>
						<th>{t('manual.role')}</th>
						<th>{t('manual.filesystem')}</th>
						<th class="text-right"></th>
					</tr>
				</thead>
				<tbody>
					{#each layout.partitions as part (part.index)}
						<tr class={['editor-row', { designated: part.role === ROLE_BOOT || part.role === ROLE_ROOT }]}>
							<td class="part-name">
								{#if part.path}
									{part.path}
									{#if part.existingFstype}
										<span class="part-existing">{t('manual.existing')} {part.existingFstype}</span>
									{/if}
								{:else}
									<span class="part-new">{t('manual.newPart')}</span>
								{/if}
							</td>
							<td class="text-right monospace">{part.sizeMB} {t('unit.mb')}</td>
							<td>
								<div class="role-pills">
									{#each ROLE_OPTIONS as r (r)}
										<button
											type="button"
											class={['role-pill', { selected: part.role === r }]}
											onclick={() => setRole(part, r)}
										>
											{roleLabel(r)}
										</button>
									{/each}
								</div>
							</td>
							<td>
								{#if part.role === ''}
									<span class="role-fs role-preserve">—</span>
								{:else if part.role === ROLE_BOOT}
									<span class="role-fs fs-vfat">vfat</span>
								{:else}
									<span class="role-fs">{t('fs.' + fsForRole(part.role))}</span>
								{/if}
							</td>
							<td class="text-right">
								<button
									type="button"
									class={['delete-btn', { disabled: !canDelete(part) }]}
									disabled={!canDelete(part)}
									onclick={() => requestDelete(part.index)}
									aria-label={t('manual.delete')}
								>
									×
								</button>
							</td>
						</tr>
					{/each}
				</tbody>
			</table>
		</div>

		<!-- Add new partition control -->
		<div class="add-control">
			<span class="add-label">{t('manual.add')}</span>
			<input
				type="number"
				min="1"
				class="add-input"
				bind:value={addSizeMB}
				disabled={addUseRemaining}
				placeholder={t('manual.sizeMB')}
			/>
			<label class="add-check">
				<input type="checkbox" bind:checked={addUseRemaining} />
				<span>{t('manual.useRemaining')}</span>
			</label>
			<div class="role-pills add-role">
				{#each ADD_ROLE_OPTIONS as r (r)}
					<button
						type="button"
						class={['role-pill', { selected: addRole === r }]}
						onclick={() => { addRole = r; }}
					>
						{roleLabel(r)}
					</button>
				{/each}
			</div>
			<button
				type="button"
				class="add-btn"
				disabled={freeMB <= 0}
				onclick={addPartition}
			>
				+ {t('manual.add')}
			</button>
		</div>

	{/if}

	<!-- Delete confirmation dialog -->
	{#if deleteTargetIndex !== null && layout}
		<div
			class="dialog-overlay"
			role="presentation"
			onclick={() => (deleteTargetIndex = null)}
			onkeydown={(e) => { if (e.key === 'Escape') deleteTargetIndex = null; }}
		>
			<div
				class="dialog"
				role="dialog"
				aria-modal="true"
				aria-labelledby="delete-dialog-title"
				tabindex="-1"
				onclick={(e) => e.stopPropagation()}
				onkeydown={(e) => e.stopPropagation()}
			>
				<h2 id="delete-dialog-title" class="dialog-title">{t('manual.deleteTitle')}</h2>
				<p class="dialog-message">
					{t('manual.deleteMessage')}
				</p>
				<div class="dialog-actions">
					<button type="button" class="btn-cancel" onclick={() => (deleteTargetIndex = null)}>
						{t('dialog.confirm.cancel')}
					</button>
					<button type="button" class="btn-confirm danger" onclick={confirmDelete}>
						{t('manual.deleteConfirm')}
					</button>
				</div>
			</div>
		</div>
	{/if}
</div>

